import pandas as pd
import numpy as np

DEFAULT_COLUMNS = ['Element', 'Count']

def task_func(elements, include_index=False):
    rows = []
    for i, element in enumerate(elements):
        row = {
            'Element': element,
            'Count': len(element)
        }
        if include_index:
            row['Index'] = i
        rows.append(row)

    if include_index:
        return pd.DataFrame(rows, columns=['Index'] + DEFAULT_COLUMNS)
    return pd.DataFrame(rows, columns=DEFAULT_COLUMNS)
